-- Pós-check read-only da migration 20261105_comercial_hardening.sql
SELECT c.relname AS tabela,t.tgname AS trigger,pg_get_triggerdef(t.oid) AS definicao
FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND NOT t.tgisinternal AND t.tgname IN('guard_profile_tenant_change','set_orcamento_organization','enforce_organization_budget_limit','enforce_organization_member_limit') ORDER BY c.relname,t.tgname;
SELECT schemaname,tablename,policyname,cmd,roles,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename IN('profiles','orcamentos','orcamento_itens','orcamento_cronograma') ORDER BY tablename,policyname;
SELECT routine_schema,routine_name,security_type FROM information_schema.routines WHERE routine_schema='public' AND routine_name IN('calcular_custo_composicao','can_read_orcamento','can_edit_orcamento','can_delete_orcamento','guard_profile_tenant_change') ORDER BY routine_name;
SELECT p.oid::regprocedure AS funcao,has_function_privilege('anon',p.oid,'EXECUTE') AS anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') AS authenticated_execute,has_function_privilege('service_role',p.oid,'EXECUTE') AS service_role_execute FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('calcular_custo_composicao','can_read_orcamento','can_edit_orcamento','can_delete_orcamento');
SELECT count(*) FILTER(WHERE p.id_empresa IS NOT NULL AND m.user_id IS NULL) AS profiles_sem_membership,count(*) FILTER(WHERE o.organization_id IS NULL AND p.id_empresa IS NOT NULL) AS orcamentos_sem_tenant,count(*) AS total_profiles FROM public.profiles p LEFT JOIN public.organization_members m ON m.user_id=p.id AND m.organization_id=p.id_empresa LEFT JOIN public.orcamentos o ON o.user_id=p.id;
SELECT s.organization_id,s.plan_code,s.status,s.trial_ends_at,s.current_period_end,p.max_users,p.max_budgets,p.max_import_rows FROM public.organization_subscriptions s JOIN public.plan_definitions p ON p.code=s.plan_code ORDER BY s.organization_id;
SELECT count(*) AS itens_analiticos_sem_pai FROM public.catalogo_composicao_itens ci LEFT JOIN public.catalogo_composicoes c ON c.codigo=ci.codigo_composicao AND c.fonte=ci.fonte WHERE c.codigo IS NULL;
